  def num_bank = 4                  // # of banks for register file
  def num_collectorUnit = num_warp
  def num_vgpr:Int = 128*num_warp
  def num_sgpr:Int = 256*num_warp
  def depth_regBank = log2Ceil(num_vgpr/num_bank)
